    pub fn asGap(self: Item) ?Gap {
        if (!self.node.isA(.gap)) return null;
        return Gap{ .node = self.node };
    }
};

/// A Transition is a `Transition`.
///
/// It is a Composable, so every method of one is written out here too.
pub const Transition = struct {
    /// The object this is, and the document it lives in.
    node: Node,

    /// init creates a transition. Its offsets start at zero.
    ///
    /// A null new_name means none.
    ///
    /// A null transition_type means none.
    ///
    /// C: `otio_transition_new`
    pub fn init(document: *Document, new_name: ?[:0]const u8, transition_type: ?[:0]const u8) Error!Transition {
        const arg_new_name: ?[*:0]const u8 = if (new_name) |text| text.ptr else null;
        const arg_transition_type: ?[*:0]const u8 = if (transition_type) |text| text.ptr else null;
        var out_node: c.NodeHandle = undefined;
        const status = c.otio_transition_new(document, arg_new_name, arg_transition_type, &out_node);
        if (status != .ok) return support.statusError(status);
        return Transition{ .node = Node{ .doc = document, .handle = out_node } };
    }

    /// Whether the object may be used with a document. See
    /// `Node.belongsTo`.
    pub fn belongsTo(self: Transition, owner: ?*Document) bool {
        return self.node.belongsTo(owner);
    }

    /// Whether the object is of a schema, or of one deriving from it.
    /// See `Node.isA`.
    pub fn isA(self: Transition, schema: NodeKind) bool {
        return self.node.isA(schema);
    }

    /// The object's metadata, which is a dictionary of its own.
    ///
    /// A path names a value inside it, a step at a time, separated by
    /// dots: "cmx_3600.reel" reaches the reel of the dictionary the EDL
    /// adapter left behind, and "takes[0]" the first entry of a list.
    pub fn metadata(self: Transition) Metadata {
        return Metadata{ .node = self.node };
    }

    /// enabled returns whether a transition is applied.
    ///
    /// C: `otio_transition_enabled`
    pub fn enabled(self: Transition) Error!bool {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_enabled: bool = undefined;
        const status = c.otio_transition_enabled(doc, self.node.handle, &out_enabled);
        if (status != .ok) return support.statusError(status);
        return out_enabled;
    }

    /// inOffset returns how far a transition reaches into the item before
    /// it.
    ///
    /// C: `otio_transition_in_offset`
    pub fn inOffset(self: Transition) Error!RationalTime {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_offset: RationalTime = undefined;
        const status = c.otio_transition_in_offset(doc, self.node.handle, &out_offset);
        if (status != .ok) return support.statusError(status);
        return out_offset;
    }

    /// outOffset returns how far a transition reaches into the item after
    /// it.
    ///
    /// C: `otio_transition_out_offset`
    pub fn outOffset(self: Transition) Error!RationalTime {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_offset: RationalTime = undefined;
        const status = c.otio_transition_out_offset(doc, self.node.handle, &out_offset);
        if (status != .ok) return support.statusError(status);
        return out_offset;
    }

    /// setEnabled sets whether a transition is applied.
    ///
    /// C: `otio_transition_set_enabled`
    pub fn setEnabled(self: Transition, new_enabled: bool) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_transition_set_enabled(doc, self.node.handle, new_enabled);
        if (status != .ok) return support.statusError(status);
    }

    /// setInOffset sets how far a transition reaches into the item before
    /// it.
    ///
    /// C: `otio_transition_set_in_offset`
    pub fn setInOffset(self: Transition, offset: RationalTime) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_transition_set_in_offset(doc, self.node.handle, offset);
        if (status != .ok) return support.statusError(status);
    }

    /// setOutOffset sets how far a transition reaches into the item after
    /// it.
    ///
    /// C: `otio_transition_set_out_offset`
    pub fn setOutOffset(self: Transition, offset: RationalTime) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_transition_set_out_offset(doc, self.node.handle, offset);
        if (status != .ok) return support.statusError(status);
    }

    /// setTransitionType sets the kind of transition.
    ///
    /// C: `otio_transition_set_type`
    pub fn setTransitionType(self: Transition, transition_type: [:0]const u8) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_transition_set_type(doc, self.node.handle, transition_type.ptr);
        if (status != .ok) return support.statusError(status);
    }

    /// transitionType returns the kind of transition, such as
    /// `"SMPTE_Dissolve"`.
    ///
    /// What this hands back was allocated with allocator, and is the
    /// caller's to free.
    ///
    /// C: `otio_transition_type`
    pub fn transitionType(self: Transition, allocator: Allocator) Error![]u8 {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_type: c.Buffer = undefined;
        const status = c.otio_transition_type(doc, self.node.handle, &out_type);
        if (status != .ok) return support.statusError(status);
        defer c.otio_buffer_free(out_type);
        return try support.copyBuffer(allocator, out_type);
    }

    /// childAt returns one of an object's children.
    ///
    /// See `Node.childAt`.
    pub fn childAt(self: Transition, index: usize) Error!Node {
        return self.node.childAt(index);
    }

    /// childCount returns how many children an object holds.
    ///
    /// See `Node.childCount`.
    pub fn childCount(self: Transition) Error!usize {
        return self.node.childCount();
    }

    /// children returns an object's children.
    ///
    /// See `Node.children`.
    pub fn children(self: Transition, allocator: Allocator) Error![]Node {
        return self.node.children(allocator);
    }

    /// equals returns whether two handles name the same object.
    ///
    /// See `Node.equals`.
    pub fn equals(self: Transition, right: Node) bool {
        return self.node.equals(right);
    }

    /// findClips returns every clip at or below an object, in order.
    ///
    /// See `Node.findClips`.
    pub fn findClips(self: Transition, allocator: Allocator) Error![]Node {
        return self.node.findClips(allocator);
    }

    /// highestAncestor returns the outermost object above this one.
    ///
    /// See `Node.highestAncestor`.
    pub fn highestAncestor(self: Transition) Error!Node {
        return self.node.highestAncestor();
    }

    /// isNone returns whether a handle names no object.
    ///
    /// See `Node.isNone`.
    pub fn isNone(self: Transition) bool {
        return self.node.isNone();
    }

    /// schemaKind returns what kind of object a handle names.
    ///
    /// See `Node.schemaKind`.
    pub fn schemaKind(self: Transition) Error!NodeKind {
        return self.node.schemaKind();
    }

    /// name returns an object's name, which is empty for an object that has
    /// none.
    ///
    /// See `Node.name`.
    pub fn name(self: Transition, allocator: Allocator) Error![]u8 {
        return self.node.name(allocator);
    }

    /// overlapping returns whether an object sits over its neighbours
    /// rather than beside them.
    ///
    /// See `Node.overlapping`.
    pub fn overlapping(self: Transition) Error!bool {
        return self.node.overlapping();
    }

    /// parent returns the composition an object sits in.
    ///
    /// See `Node.parent`.
    pub fn parent(self: Transition) Error!?Node {
        return self.node.parent();
    }

    /// schemaName returns the schema name an object serializes as, such as
    /// `"Clip"`.
    ///
    /// See `Node.schemaName`.
    pub fn schemaName(self: Transition, allocator: Allocator) Error![]u8 {
        return self.node.schemaName(allocator);
    }

    /// schemaVersion returns the schema version an object serializes as.
    ///
    /// See `Node.schemaVersion`.
    pub fn schemaVersion(self: Transition) Error!u32 {
        return self.node.schemaVersion();
    }

    /// setName sets an object's name.
    ///
    /// See `Node.setName`.
    pub fn setName(self: Transition, new_name: [:0]const u8) Error!void {
        return self.node.setName(new_name);
    }

    /// toJson writes one object of a document as OTIO JSON.
    ///
    /// See `Node.toJson`.
    pub fn toJson(self: Transition, allocator: Allocator, indent: usize) Error![]u8 {
        return self.node.toJson(allocator, indent);
    }

    /// transformedTime restates an instant from one object's clock in
    /// another's.
    ///
    /// See `Node.transformedTime`.
    pub fn transformedTime(self: Transition, time: RationalTime, to: Node) Error!RationalTime {
        return self.node.transformedTime(time, to);
    }

    /// transformedTimeRange restates a span from one object's clock in
