/// A Track is a `Track`.
///
/// It is a Composition, so every method of one is written out here too.
pub const Track = struct {
    /// The object this is, and the document it lives in.
    node: Node,

    /// init creates a track. `kind` may be null, which means `"Video"`, as
    /// upstream's default does.
    ///
    /// C: `otio_track_new`
    pub fn init(document: *Document, new_name: ?[:0]const u8, new_kind: ?[:0]const u8) Error!Track {
        const arg_new_name: ?[*:0]const u8 = if (new_name) |text| text.ptr else null;
        const arg_new_kind: ?[*:0]const u8 = if (new_kind) |text| text.ptr else null;
        var out_node: c.NodeHandle = undefined;
        const status = c.otio_track_new(document, arg_new_name, arg_new_kind, &out_node);
        if (status != .ok) return support.statusError(status);
        return Track{ .node = Node{ .doc = document, .handle = out_node } };
    }

    /// Whether the object may be used with a document. See
    /// `Node.belongsTo`.
    pub fn belongsTo(self: Track, owner: ?*Document) bool {
        return self.node.belongsTo(owner);
    }

    /// Whether the object is of a schema, or of one deriving from it.
    /// See `Node.isA`.
    pub fn isA(self: Track, schema: NodeKind) bool {
        return self.node.isA(schema);
    }

    /// The object's metadata, which is a dictionary of its own.
    ///
    /// A path names a value inside it, a step at a time, separated by
    /// dots: "cmx_3600.reel" reaches the reel of the dictionary the EDL
    /// adapter left behind, and "takes[0]" the first entry of a list.
    pub fn metadata(self: Track) Metadata {
        return Metadata{ .node = self.node };
    }

    /// kind returns what a track carries, such as `"Video"` or `"Audio"`.
    ///
    /// What this hands back was allocated with allocator, and is the
    /// caller's to free.
    ///
    /// C: `otio_track_kind`
    pub fn kind(self: Track, allocator: Allocator) Error![]u8 {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_kind: c.Buffer = undefined;
        const status = c.otio_track_kind(doc, self.node.handle, &out_kind);
        if (status != .ok) return support.statusError(status);
        defer c.otio_buffer_free(out_kind);
        return try support.copyBuffer(allocator, out_kind);
    }

    /// setKind sets what a track carries.
    ///
    /// C: `otio_track_set_kind`
    pub fn setKind(self: Track, new_kind: [:0]const u8) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_track_set_kind(doc, self.node.handle, new_kind.ptr);
        if (status != .ok) return support.statusError(status);
    }

    /// appendChild adds a child to the end of a composition.
    ///
    /// See `Composition.appendChild`.
    pub fn appendChild(self: Track, child: Node) Error!void {
        return (Composition{ .node = self.node }).appendChild(child);
    }

    /// childAtTime returns the child of a composition that covers an
    /// instant.
    ///
    /// See `Composition.childAtTime`.
    pub fn childAtTime(self: Track, time: RationalTime, shallow: bool) Error!?Node {
        return (Composition{ .node = self.node }).childAtTime(time, shallow);
    }

    /// childrenInRange returns the children of a composition that touch a
    /// span.
    ///
    /// See `Composition.childrenInRange`.
    pub fn childrenInRange(self: Track, allocator: Allocator, search_range: TimeRange) Error![]Node {
        return (Composition{ .node = self.node }).childrenInRange(allocator, search_range);
    }

    /// clearChildren removes every child of a composition, and returns
    /// them.
    ///
    /// See `Composition.clearChildren`.
    pub fn clearChildren(self: Track, allocator: Allocator) Error![]Node {
        return (Composition{ .node = self.node }).clearChildren(allocator);
    }

    /// detachChild removes a child by handle.
    ///
    /// See `Composition.detachChild`.
    pub fn detachChild(self: Track, child: Node) Error!void {
        return (Composition{ .node = self.node }).detachChild(child);
    }

    /// findChildrenOfKind returns every object of a kind at or below a
    /// composition.
    ///
    /// See `Composition.findChildrenOfKind`.
    pub fn findChildrenOfKind(self: Track, allocator: Allocator, new_kind: NodeKind, search_range: ?TimeRange, shallow: bool) Error![]Node {
        return (Composition{ .node = self.node }).findChildrenOfKind(allocator, new_kind, search_range, shallow);
    }

    /// handlesOfChild returns how much unused media a child has on each
    /// side.
    ///
    /// See `Composition.handlesOfChild`.
    pub fn handlesOfChild(self: Track, child: Node) Error!Handles {
        return (Composition{ .node = self.node }).handlesOfChild(child);
    }

    /// hasChild returns whether a composition holds an object directly.
    ///
    /// See `Composition.hasChild`.
    pub fn hasChild(self: Track, child: Node) Error!bool {
        return (Composition{ .node = self.node }).hasChild(child);
    }

    /// indexOfChild returns where a child sits in its composition.
    ///
    /// See `Composition.indexOfChild`.
    pub fn indexOfChild(self: Track, child: Node) Error!usize {
        return (Composition{ .node = self.node }).indexOfChild(child);
    }

    /// insertChild adds a child to a composition at an index.
    ///
    /// See `Composition.insertChild`.
    pub fn insertChild(self: Track, index: i64, child: Node) Error!void {
        return (Composition{ .node = self.node }).insertChild(index, child);
    }

    /// isParentOf returns whether an object descends from a composition at
    /// any depth.
    ///
    /// See `Composition.isParentOf`.
    pub fn isParentOf(self: Track, other: Node) Error!bool {
        return (Composition{ .node = self.node }).isParentOf(other);
    }

    /// neighborsOf returns the children on either side of one, or `none`
    /// where there is none.
    ///
    /// See `Composition.neighborsOf`.
    pub fn neighborsOf(self: Track, child: Node, policy: NeighborGapPolicy) Error!Composition.NeighborsOfResult {
        return (Composition{ .node = self.node }).neighborsOf(child, policy);
    }

    /// rangeOfChild returns where a child sits in a composition's clock, at
    /// any depth.
    ///
    /// See `Composition.rangeOfChild`.
    pub fn rangeOfChild(self: Track, child: Node) Error!TimeRange {
        return (Composition{ .node = self.node }).rangeOfChild(child);
    }

    /// rangeOfChildAtIndex returns where the child at an index sits in its
    /// composition's clock.
    ///
    /// See `Composition.rangeOfChildAtIndex`.
    pub fn rangeOfChildAtIndex(self: Track, index: i64) Error!TimeRange {
        return (Composition{ .node = self.node }).rangeOfChildAtIndex(index);
    }

    /// rangesOfChildren returns where every child of a composition sits, in
    /// one pass.
    ///
    /// See `Composition.rangesOfChildren`.
    pub fn rangesOfChildren(self: Track, allocator: Allocator) Error!Composition.RangesOfChildrenResult {
        return (Composition{ .node = self.node }).rangesOfChildren(allocator);
    }

    /// removeChild removes a child by index, and returns it.
    ///
    /// See `Composition.removeChild`.
    pub fn removeChild(self: Track, index: i64) Error!Node {
        return (Composition{ .node = self.node }).removeChild(index);
    }

    /// trimChildRange clips a range to a composition's own trim.
    ///
    /// See `Composition.trimChildRange`.
    pub fn trimChildRange(self: Track, child_range: TimeRange) Error!?TimeRange {
        return (Composition{ .node = self.node }).trimChildRange(child_range);
    }

    /// trimmedRangeOfChild returns where a child sits after the
    /// composition's trim, at any depth.
    ///
    /// See `Composition.trimmedRangeOfChild`.
    pub fn trimmedRangeOfChild(self: Track, child: Node) Error!?TimeRange {
        return (Composition{ .node = self.node }).trimmedRangeOfChild(child);
    }

    /// trimmedRangeOfChildAtIndex returns where the child at an index sits,
    /// after the composition's own trim.
    ///
    /// See `Composition.trimmedRangeOfChildAtIndex`.
    pub fn trimmedRangeOfChildAtIndex(self: Track, index: i64) Error!TimeRange {
        return (Composition{ .node = self.node }).trimmedRangeOfChildAtIndex(index);
    }

    /// appendEffect adds an effect to an item. Effects apply in the order
    /// they are added.
    ///
    /// See `Item.appendEffect`.
    pub fn appendEffect(self: Track, effect_handle: Node) Error!void {
        return (Item{ .node = self.node }).appendEffect(effect_handle);
    }

    /// appendMarker adds a marker to an item.
    ///
    /// See `Item.appendMarker`.
    pub fn appendMarker(self: Track, marker_handle: Node) Error!void {
        return (Item{ .node = self.node }).appendMarker(marker_handle);
    }

    /// availableRange returns the span of media an object could draw on,
    /// before trimming.
    ///
    /// See `Item.availableRange`.
    pub fn availableRange(self: Track) Error!TimeRange {
        return (Item{ .node = self.node }).availableRange();
    }

    /// clearColor clears an item's display tint.
    ///
    /// See `Item.clearColor`.
    pub fn clearColor(self: Track) Error!void {
        return (Item{ .node = self.node }).clearColor();
    }

    /// clearSourceRange clears an item's source range, so that it takes all
    /// of its media.
    ///
    /// See `Item.clearSourceRange`.
    pub fn clearSourceRange(self: Track) Error!void {
        return (Item{ .node = self.node }).clearSourceRange();
    }

    /// color returns an item's display tint, and the name that goes with
    /// it.
    ///
    /// See `Item.color`.
    pub fn color(self: Track, allocator: Allocator) Error!?Item.ColorResult {
        return (Item{ .node = self.node }).color(allocator);
    }

    /// duration returns how long an object occupies its parent's timeline.
    ///
    /// See `Item.duration`.
    pub fn duration(self: Track) Error!RationalTime {
        return (Item{ .node = self.node }).duration();
    }

    /// effectAt returns one of an item's effects.
    ///
    /// See `Item.effectAt`.
    pub fn effectAt(self: Track, index: usize) Error!Node {
        return (Item{ .node = self.node }).effectAt(index);
    }

    /// effectCount returns how many effects an item carries.
    ///
    /// See `Item.effectCount`.
    pub fn effectCount(self: Track) Error!usize {
        return (Item{ .node = self.node }).effectCount();
    }

    /// enabled returns whether an item contributes to its composition.
    ///
    /// See `Item.enabled`.
    pub fn enabled(self: Track) Error!bool {
        return (Item{ .node = self.node }).enabled();
    }

    /// markerAt returns one of an item's markers.
    ///
    /// See `Item.markerAt`.
    pub fn markerAt(self: Track, index: usize) Error!Node {
        return (Item{ .node = self.node }).markerAt(index);
    }

    /// markerCount returns how many markers an item carries.
    ///
    /// See `Item.markerCount`.
    pub fn markerCount(self: Track) Error!usize {
        return (Item{ .node = self.node }).markerCount();
    }

    /// rangeInParent returns where an object sits in its parent's clock.
    ///
    /// See `Item.rangeInParent`.
    pub fn rangeInParent(self: Track) Error!TimeRange {
        return (Item{ .node = self.node }).rangeInParent();
    }

    /// removeEffect removes one of an item's effects, and returns it.
    ///
    /// See `Item.removeEffect`.
    pub fn removeEffect(self: Track, index: usize) Error!Node {
        return (Item{ .node = self.node }).removeEffect(index);
    }

    /// removeMarker removes one of an item's markers, and returns it.
    ///
    /// See `Item.removeMarker`.
    pub fn removeMarker(self: Track, index: usize) Error!Node {
        return (Item{ .node = self.node }).removeMarker(index);
    }

    /// setColor sets an item's display tint. `name` may be null for an
    /// unnamed colour.
    ///
    /// See `Item.setColor`.
    pub fn setColor(self: Track, new_color: Color, new_name: ?[:0]const u8) Error!void {
        return (Item{ .node = self.node }).setColor(new_color, new_name);
    }

    /// setEnabled sets whether an item contributes to its composition.
    ///
    /// See `Item.setEnabled`.
    pub fn setEnabled(self: Track, new_enabled: bool) Error!void {
        return (Item{ .node = self.node }).setEnabled(new_enabled);
    }

    /// setSourceRange sets the portion of its media an item uses.
    ///
    /// See `Item.setSourceRange`.
    pub fn setSourceRange(self: Track, range: TimeRange) Error!void {
        return (Item{ .node = self.node }).setSourceRange(range);
    }

    /// sourceRange returns the portion of its media an item uses.
    ///
    /// See `Item.sourceRange`.
    pub fn sourceRange(self: Track) Error!?TimeRange {
        return (Item{ .node = self.node }).sourceRange();
    }

    /// trimmedRange returns the span of media an object uses, in its own
    /// clock.
    ///
    /// See `Item.trimmedRange`.
    pub fn trimmedRange(self: Track) Error!TimeRange {
        return (Item{ .node = self.node }).trimmedRange();
    }

    /// trimmedRangeInParent returns where an object sits in its parent's
    /// clock, after the parent's own trim.
    ///
    /// See `Item.trimmedRangeInParent`.
    pub fn trimmedRangeInParent(self: Track) Error!?TimeRange {
        return (Item{ .node = self.node }).trimmedRangeInParent();
    }

    /// visibleRange returns the span of media an object shows, including
    /// what its transitions reach into.
    ///
    /// See `Item.visibleRange`.
    pub fn visibleRange(self: Track) Error!TimeRange {
        return (Item{ .node = self.node }).visibleRange();
    }

    /// childAt returns one of an object's children.
    ///
    /// See `Node.childAt`.
    pub fn childAt(self: Track, index: usize) Error!Node {
        return self.node.childAt(index);
    }

    /// childCount returns how many children an object holds.
    ///
    /// See `Node.childCount`.
    pub fn childCount(self: Track) Error!usize {
        return self.node.childCount();
    }

    /// children returns an object's children.
    ///
    /// See `Node.children`.
    pub fn children(self: Track, allocator: Allocator) Error![]Node {
        return self.node.children(allocator);
    }

    /// equals returns whether two handles name the same object.
    ///
    /// See `Node.equals`.
    pub fn equals(self: Track, right: Node) bool {
        return self.node.equals(right);
    }

    /// findClips returns every clip at or below an object, in order.
    ///
    /// See `Node.findClips`.
    pub fn findClips(self: Track, allocator: Allocator) Error![]Node {
        return self.node.findClips(allocator);
    }

    /// highestAncestor returns the outermost object above this one.
    ///
    /// See `Node.highestAncestor`.
    pub fn highestAncestor(self: Track) Error!Node {
        return self.node.highestAncestor();
    }

    /// isNone returns whether a handle names no object.
    ///
    /// See `Node.isNone`.
    pub fn isNone(self: Track) bool {
        return self.node.isNone();
    }

    /// schemaKind returns what kind of object a handle names.
    ///
    /// See `Node.schemaKind`.
    pub fn schemaKind(self: Track) Error!NodeKind {
        return self.node.schemaKind();
    }

    /// name returns an object's name, which is empty for an object that has
    /// none.
    ///
    /// See `Node.name`.
    pub fn name(self: Track, allocator: Allocator) Error![]u8 {
        return self.node.name(allocator);
    }

    /// overlapping returns whether an object sits over its neighbours
    /// rather than beside them.
    ///
    /// See `Node.overlapping`.
    pub fn overlapping(self: Track) Error!bool {
        return self.node.overlapping();
    }

    /// parent returns the composition an object sits in.
    ///
    /// See `Node.parent`.
    pub fn parent(self: Track) Error!?Node {
        return self.node.parent();
    }

    /// schemaName returns the schema name an object serializes as, such as
    /// `"Clip"`.
    ///
    /// See `Node.schemaName`.
    pub fn schemaName(self: Track, allocator: Allocator) Error![]u8 {
        return self.node.schemaName(allocator);
    }

    /// schemaVersion returns the schema version an object serializes as.
    ///
    /// See `Node.schemaVersion`.
    pub fn schemaVersion(self: Track) Error!u32 {
        return self.node.schemaVersion();
    }

    /// setName sets an object's name.
    ///
    /// See `Node.setName`.
    pub fn setName(self: Track, new_name: [:0]const u8) Error!void {
        return self.node.setName(new_name);
    }

    /// toJson writes one object of a document as OTIO JSON.
    ///
    /// See `Node.toJson`.
    pub fn toJson(self: Track, allocator: Allocator, indent: usize) Error![]u8 {
        return self.node.toJson(allocator, indent);
    }

    /// transformedTime restates an instant from one object's clock in
    /// another's.
    ///
    /// See `Node.transformedTime`.
    pub fn transformedTime(self: Track, time: RationalTime, to: Node) Error!RationalTime {
        return self.node.transformedTime(time, to);
    }

    /// transformedTimeRange restates a span from one object's clock in
    /// another's.
    ///
    /// See `Node.transformedTimeRange`.
    pub fn transformedTimeRange(self: Track, range: TimeRange, to: Node) Error!TimeRange {
        return self.node.transformedTimeRange(range, to);
    }

    /// visible returns whether an object covers what is beneath it when its
    /// composition is flattened.
    ///
    /// See `Node.visible`.
    pub fn visible(self: Track) Error!bool {
        return self.node.visible();
    }

    /// The same object, seen as the Composition it is.
    pub fn asComposition(self: Track) Composition {
        return Composition{ .node = self.node };
    }

    /// The same object, seen as the Item it is.
    pub fn asItem(self: Track) Item {
        return Item{ .node = self.node };
    }

    /// The same object, seen as the Composable it is.
    pub fn asComposable(self: Track) Composable {
        return Composable{ .node = self.node };
    }

    /// The same object, seen as the SerializableObjectWithMetadata it is.
    pub fn asSerializableObjectWithMetadata(self: Track) SerializableObjectWithMetadata {
        return SerializableObjectWithMetadata{ .node = self.node };
    }

    /// The same object, seen as the Node it is.
    pub fn asNode(self: Track) Node {
        return self.node;
    }
};

/// A Stack is a `Stack`.
///
/// It is a Composition, so every method of one is written out here too.
pub const Stack = struct {
    /// The object this is, and the document it lives in.
    node: Node,

    /// init creates a stack.
    ///
    /// A null new_name means none.
    ///
    /// C: `otio_stack_new`
    pub fn init(document: *Document, new_name: ?[:0]const u8) Error!Stack {
        const arg_new_name: ?[*:0]const u8 = if (new_name) |text| text.ptr else null;
        var out_node: c.NodeHandle = undefined;
        const status = c.otio_stack_new(document, arg_new_name, &out_node);
        if (status != .ok) return support.statusError(status);
        return Stack{ .node = Node{ .doc = document, .handle = out_node } };
    }

    /// Whether the object may be used with a document. See
    /// `Node.belongsTo`.
    pub fn belongsTo(self: Stack, owner: ?*Document) bool {
        return self.node.belongsTo(owner);
    }

    /// Whether the object is of a schema, or of one deriving from it.
    /// See `Node.isA`.
    pub fn isA(self: Stack, schema: NodeKind) bool {
        return self.node.isA(schema);
    }

    /// The object's metadata, which is a dictionary of its own.
    ///
    /// A path names a value inside it, a step at a time, separated by
    /// dots: "cmx_3600.reel" reaches the reel of the dictionary the EDL
    /// adapter left behind, and "takes[0]" the first entry of a list.
    pub fn metadata(self: Stack) Metadata {
        return Metadata{ .node = self.node };
