        return (Composition{ .node = self.node }).detachChild(child);
    }

    /// findChildrenOfKind returns every object of a kind at or below a
    /// composition.
    ///
    /// See `Composition.findChildrenOfKind`.
    pub fn findChildrenOfKind(self: Stack, allocator: Allocator, new_kind: NodeKind, search_range: ?TimeRange, shallow: bool) Error![]Node {
        return (Composition{ .node = self.node }).findChildrenOfKind(allocator, new_kind, search_range, shallow);
    }

    /// handlesOfChild returns how much unused media a child has on each
    /// side.
    ///
    /// See `Composition.handlesOfChild`.
    pub fn handlesOfChild(self: Stack, child: Node) Error!Handles {
        return (Composition{ .node = self.node }).handlesOfChild(child);
    }

    /// hasChild returns whether a composition holds an object directly.
    ///
    /// See `Composition.hasChild`.
    pub fn hasChild(self: Stack, child: Node) Error!bool {
