/// A Clip is a `Clip`.
///
/// It is a Item, so every method of one is written out here too.
pub const Clip = struct {
    /// The object this is, and the document it lives in.
    node: Node,

    /// init creates a clip. `name` may be null for an unnamed one.
    ///
    /// C: `otio_clip_new`
    pub fn init(document: *Document, new_name: ?[:0]const u8) Error!Clip {
        const arg_new_name: ?[*:0]const u8 = if (new_name) |text| text.ptr else null;
        var out_node: c.NodeHandle = undefined;
        const status = c.otio_clip_new(document, arg_new_name, &out_node);
        if (status != .ok) return support.statusError(status);
        return Clip{ .node = Node{ .doc = document, .handle = out_node } };
    }

    /// Whether the object may be used with a document. See
    /// `Node.belongsTo`.
    pub fn belongsTo(self: Clip, owner: ?*Document) bool {
        return self.node.belongsTo(owner);
    }

    /// Whether the object is of a schema, or of one deriving from it.
    /// See `Node.isA`.
    pub fn isA(self: Clip, schema: NodeKind) bool {
        return self.node.isA(schema);
    }

    /// The object's metadata, which is a dictionary of its own.
    ///
    /// A path names a value inside it, a step at a time, separated by
    /// dots: "cmx_3600.reel" reaches the reel of the dictionary the EDL
    /// adapter left behind, and "takes[0]" the first entry of a list.
    pub fn metadata(self: Clip) Metadata {
        return Metadata{ .node = self.node };
    }

    /// activeMediaReferenceKey returns which of a clip's media references
    /// is in use.
    ///
    /// What this hands back was allocated with allocator, and is the
    /// caller's to free.
    ///
    /// C: `otio_clip_active_media_reference_key`
    pub fn activeMediaReferenceKey(self: Clip, allocator: Allocator) Error![]u8 {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_key: c.Buffer = undefined;
        const status = c.otio_clip_active_media_reference_key(doc, self.node.handle, &out_key);
        if (status != .ok) return support.statusError(status);
        defer c.otio_buffer_free(out_key);
        return try support.copyBuffer(allocator, out_key);
    }

    /// mediaReference returns one of a clip's media references.
    ///
    /// A null `key` means the active one. Reports `Status.no_value` if the
    /// key names nothing, which for the active key is a clip with no media.
    ///
    /// C: `otio_clip_media_reference`
    pub fn mediaReference(self: Clip, key: ?[:0]const u8) Error!?Node {
        const doc = self.node.doc orelse return Error.NullPointer;
        const arg_key: ?[*:0]const u8 = if (key) |text| text.ptr else null;
        var out_reference: c.NodeHandle = undefined;
        const status = c.otio_clip_media_reference(doc, self.node.handle, arg_key, &out_reference);
        if (status == .no_value) return null;
        if (status != .ok) return support.statusError(status);
        return Node{ .doc = self.node.doc, .handle = out_reference };
    }

    /// mediaReferenceCount returns how many media references a clip holds.
    ///
    /// C: `otio_clip_media_reference_count`
    pub fn mediaReferenceCount(self: Clip) Error!usize {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_count: usize = undefined;
        const status = c.otio_clip_media_reference_count(doc, self.node.handle, &out_count);
        if (status != .ok) return support.statusError(status);
        return out_count;
    }

    /// mediaReferenceKeyAt returns the key of one of a clip's media
    /// references.
    ///
    /// The references are ordered by key, so walking the indices walks them
    /// in a stable order.
    ///
    /// What this hands back was allocated with allocator, and is the
    /// caller's to free.
    ///
    /// C: `otio_clip_media_reference_key_at`
    pub fn mediaReferenceKeyAt(self: Clip, allocator: Allocator, index: usize) Error![]u8 {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_key: c.Buffer = undefined;
        const status = c.otio_clip_media_reference_key_at(doc, self.node.handle, index, &out_key);
        if (status != .ok) return support.statusError(status);
        defer c.otio_buffer_free(out_key);
        return try support.copyBuffer(allocator, out_key);
    }

    /// removeMediaReference removes one of a clip's media references, and
    /// returns it.
    ///
    /// Where there is nothing to report this answers null, which is an
    /// answer rather than a failure.
    ///
    /// C: `otio_clip_remove_media_reference`
    pub fn removeMediaReference(self: Clip, key: [:0]const u8) Error!?Node {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_reference: c.NodeHandle = undefined;
        const status = c.otio_clip_remove_media_reference(doc, self.node.handle, key.ptr, &out_reference);
        if (status == .no_value) return null;
        if (status != .ok) return support.statusError(status);
        return Node{ .doc = self.node.doc, .handle = out_reference };
    }

    /// setActiveMediaReferenceKey sets which of a clip's media references
    /// is in use.
    ///
    /// C: `otio_clip_set_active_media_reference_key`
    pub fn setActiveMediaReferenceKey(self: Clip, key: [:0]const u8) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_clip_set_active_media_reference_key(doc, self.node.handle, key.ptr);
        if (status != .ok) return support.statusError(status);
    }

    /// setMediaReference sets one of a clip's media references, adding it
    /// if the key is new.
    ///
    /// C: `otio_clip_set_media_reference`
    pub fn setMediaReference(self: Clip, key: [:0]const u8, reference: Node) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        if (!reference.belongsTo(self.node.doc)) return Error.ForeignObject;
        const status = c.otio_clip_set_media_reference(doc, self.node.handle, key.ptr, reference.handle);
        if (status != .ok) return support.statusError(status);
    }

