///
/// It is a SerializableObjectWithMetadata, so every method of one is
/// written out here too.
pub const Timeline = struct {
    /// The object this is, and the document it lives in.
    node: Node,

    /// init creates a timeline. Its tracks stack is not created with it;
    /// make one with [`init`] and hand it over with [`setTracks`].
    ///
    /// A null new_name means none.
    ///
    /// C: `otio_timeline_new`
    pub fn init(document: *Document, new_name: ?[:0]const u8) Error!Timeline {
        const arg_new_name: ?[*:0]const u8 = if (new_name) |text| text.ptr else null;
        var out_node: c.NodeHandle = undefined;
        const status = c.otio_timeline_new(document, arg_new_name, &out_node);
        if (status != .ok) return support.statusError(status);
        return Timeline{ .node = Node{ .doc = document, .handle = out_node } };
    }

    /// Whether the object may be used with a document. See
    /// `Node.belongsTo`.
    pub fn belongsTo(self: Timeline, owner: ?*Document) bool {
        return self.node.belongsTo(owner);
    }

    /// Whether the object is of a schema, or of one deriving from it.
    /// See `Node.isA`.
    pub fn isA(self: Timeline, schema: NodeKind) bool {
        return self.node.isA(schema);
    }

    /// The object's metadata, which is a dictionary of its own.
    ///
    /// A path names a value inside it, a step at a time, separated by
    /// dots: "cmx_3600.reel" reaches the reel of the dictionary the EDL
    /// adapter left behind, and "takes[0]" the first entry of a list.
    pub fn metadata(self: Timeline) Metadata {
        return Metadata{ .node = self.node };
    }

    /// clearGlobalStartTime clears where a timeline begins.
    ///
    /// C: `otio_timeline_clear_global_start_time`
    pub fn clearGlobalStartTime(self: Timeline) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_timeline_clear_global_start_time(doc, self.node.handle);
        if (status != .ok) return support.statusError(status);
    }

    /// globalStartTime returns where a timeline begins, such as
    /// `01:00:00:00`.
    ///
    /// Reports `Status.no_value` for a timeline that does not say.
    ///
    /// C: `otio_timeline_global_start_time`
    pub fn globalStartTime(self: Timeline) Error!?RationalTime {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_time: RationalTime = undefined;
        const status = c.otio_timeline_global_start_time(doc, self.node.handle, &out_time);
        if (status == .no_value) return null;
        if (status != .ok) return support.statusError(status);
        return out_time;
    }

    /// setGlobalStartTime sets where a timeline begins.
    ///
    /// C: `otio_timeline_set_global_start_time`
    pub fn setGlobalStartTime(self: Timeline, time: RationalTime) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        const status = c.otio_timeline_set_global_start_time(doc, self.node.handle, time);
        if (status != .ok) return support.statusError(status);
    }

    /// setTracks sets the stack holding a timeline's tracks.
    ///
    /// Passing `none` clears it. The stack's parent is set to the timeline,
    /// as upstream's does.
    ///
    /// A null new_tracks means none.
    ///
    /// C: `otio_timeline_set_tracks`
    pub fn setTracks(self: Timeline, new_tracks: ?Node) Error!void {
        const doc = self.node.doc orelse return Error.NullPointer;
        if (new_tracks) |object| if (!object.belongsTo(self.node.doc)) return Error.ForeignObject;
        const arg_new_tracks: c.NodeHandle = if (new_tracks) |object| object.handle else c.otio_node_none();
        const status = c.otio_timeline_set_tracks(doc, self.node.handle, arg_new_tracks);
        if (status != .ok) return support.statusError(status);
    }

    /// tracks returns the stack holding a timeline's tracks.
    ///
    /// Reports `Status.no_value` for a timeline that has none.
    ///
