/// A Marker is a `Marker`.
///
/// It is a SerializableObjectWithMetadata, so every method of one is
/// written out here too.
pub const Marker = struct {
    /// The object this is, and the document it lives in.
    node: Node,

    /// init creates a marker covering `marked_range`.
    ///
    /// A null new_name means none.
    ///
    /// C: `otio_marker_new`
    pub fn init(document: *Document, new_name: ?[:0]const u8, marked_range: TimeRange) Error!Marker {
        const arg_new_name: ?[*:0]const u8 = if (new_name) |text| text.ptr else null;
        var out_node: c.NodeHandle = undefined;
        const status = c.otio_marker_new(document, arg_new_name, marked_range, &out_node);
        if (status != .ok) return support.statusError(status);
        return Marker{ .node = Node{ .doc = document, .handle = out_node } };
    }

    /// Whether the object may be used with a document. See
    /// `Node.belongsTo`.
    pub fn belongsTo(self: Marker, owner: ?*Document) bool {
        return self.node.belongsTo(owner);
    }

    /// Whether the object is of a schema, or of one deriving from it.
    /// See `Node.isA`.
    pub fn isA(self: Marker, schema: NodeKind) bool {
        return self.node.isA(schema);
    }

    /// The object's metadata, which is a dictionary of its own.
    ///
    /// A path names a value inside it, a step at a time, separated by
    /// dots: "cmx_3600.reel" reaches the reel of the dictionary the EDL
    /// adapter left behind, and "takes[0]" the first entry of a list.
    pub fn metadata(self: Marker) Metadata {
        return Metadata{ .node = self.node };
    }

    /// What `color` answers with.
    pub const ColorResult = struct {
        color: Color,
        name: []u8,

        /// Gives back the memory this holds.
        pub fn deinit(self: ColorResult, allocator: Allocator) void {
            allocator.free(self.name);
        }
    };

    /// color returns a marker's tint, and the name that goes with it.
    ///
    /// `out_name` may be null if the name is not wanted. Reports
    /// `Status.no_value` for an untinted marker.
    ///
    /// What this hands back was allocated with allocator, and is the
    /// caller's to free.
    ///
    /// C: `otio_marker_color`
    pub fn color(self: Marker, allocator: Allocator) Error!?ColorResult {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_color: Color = undefined;
        var out_name: c.Buffer = undefined;
        const status = c.otio_marker_color(doc, self.node.handle, &out_color, &out_name);
        if (status == .no_value) return null;
        if (status != .ok) return support.statusError(status);
        defer c.otio_buffer_free(out_name);
        return .{
            .color = out_color,
            .name = try support.copyBuffer(allocator, out_name),
        };
    }

    /// comment returns a marker's note.
    ///
    /// What this hands back was allocated with allocator, and is the
    /// caller's to free.
    ///
    /// C: `otio_marker_comment`
    pub fn comment(self: Marker, allocator: Allocator) Error![]u8 {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_comment: c.Buffer = undefined;
        const status = c.otio_marker_comment(doc, self.node.handle, &out_comment);
        if (status != .ok) return support.statusError(status);
        defer c.otio_buffer_free(out_comment);
        return try support.copyBuffer(allocator, out_comment);
    }

    /// markedRange returns the span a marker covers.
    ///
    /// C: `otio_marker_marked_range`
    pub fn markedRange(self: Marker) Error!TimeRange {
        const doc = self.node.doc orelse return Error.NullPointer;
        var out_range: TimeRange = undefined;
        const status = c.otio_marker_marked_range(doc, self.node.handle, &out_range);
        if (status != .ok) return support.statusError(status);
        return out_range;
    }

    /// setColor sets a marker's tint. `name` may be null for an unnamed
    /// colour.
    ///
    /// C: `otio_marker_set_color`
