    /// dots: "cmx_3600.reel" reaches the reel of the dictionary the EDL
    /// adapter left behind, and "takes[0]" the first entry of a list.
    pub fn metadata(self: Other) Metadata {
        return Metadata{ .node = self.node };
    }

    /// childAt returns one of an object's children.
    ///
    /// See `Node.childAt`.
    pub fn childAt(self: Other, index: usize) Error!Node {
        return self.node.childAt(index);
    }

    /// childCount returns how many children an object holds.
    ///
    /// See `Node.childCount`.
    pub fn childCount(self: Other) Error!usize {
        return self.node.childCount();
    }

    /// children returns an object's children.
    ///
    /// See `Node.children`.
    pub fn children(self: Other, allocator: Allocator) Error![]Node {
        return self.node.children(allocator);
    }

    /// equals returns whether two handles name the same object.
    ///
    /// See `Node.equals`.
    pub fn equals(self: Other, right: Node) bool {
        return self.node.equals(right);
    }

    /// findClips returns every clip at or below an object, in order.
    ///
    /// See `Node.findClips`.
    pub fn findClips(self: Other, allocator: Allocator) Error![]Node {
        return self.node.findClips(allocator);
    }

    /// highestAncestor returns the outermost object above this one.
    ///
    /// See `Node.highestAncestor`.
    pub fn highestAncestor(self: Other) Error!Node {
        return self.node.highestAncestor();
    }

    /// isNone returns whether a handle names no object.
    ///
    /// See `Node.isNone`.
    pub fn isNone(self: Other) bool {
        return self.node.isNone();
    }

    /// schemaKind returns what kind of object a handle names.
    ///
    /// See `Node.schemaKind`.
    pub fn schemaKind(self: Other) Error!NodeKind {
        return self.node.schemaKind();
    }

    /// name returns an object's name, which is empty for an object that has
    /// none.
    ///
    /// See `Node.name`.
    pub fn name(self: Other, allocator: Allocator) Error![]u8 {
        return self.node.name(allocator);
    }

    /// overlapping returns whether an object sits over its neighbours
    /// rather than beside them.
    ///
    /// See `Node.overlapping`.
    pub fn overlapping(self: Other) Error!bool {
        return self.node.overlapping();
    }

    /// parent returns the composition an object sits in.
    ///
    /// See `Node.parent`.
    pub fn parent(self: Other) Error!?Node {
        return self.node.parent();
    }

    /// schemaName returns the schema name an object serializes as, such as
    /// `"Clip"`.
    ///
    /// See `Node.schemaName`.
    pub fn schemaName(self: Other, allocator: Allocator) Error![]u8 {
        return self.node.schemaName(allocator);
    }

    /// schemaVersion returns the schema version an object serializes as.
    ///
    /// See `Node.schemaVersion`.
    pub fn schemaVersion(self: Other) Error!u32 {
        return self.node.schemaVersion();
    }

    /// setName sets an object's name.
    ///
    /// See `Node.setName`.
    pub fn setName(self: Other, new_name: [:0]const u8) Error!void {
        return self.node.setName(new_name);
    }

    /// toJson writes one object of a document as OTIO JSON.
    ///
    /// See `Node.toJson`.
    pub fn toJson(self: Other, allocator: Allocator, indent: usize) Error![]u8 {
        return self.node.toJson(allocator, indent);
    }

    /// transformedTime restates an instant from one object's clock in
    /// another's.
    ///
    /// See `Node.transformedTime`.
    pub fn transformedTime(self: Other, time: RationalTime, to: Node) Error!RationalTime {
        return self.node.transformedTime(time, to);
    }

    /// transformedTimeRange restates a span from one object's clock in
    /// another's.
    ///
    /// See `Node.transformedTimeRange`.
    pub fn transformedTimeRange(self: Other, range: TimeRange, to: Node) Error!TimeRange {
        return self.node.transformedTimeRange(range, to);
    }

    /// visible returns whether an object covers what is beneath it when its
    /// composition is flattened.
    ///
    /// See `Node.visible`.
    pub fn visible(self: Other) Error!bool {
        return self.node.visible();
    }

    /// The same object, seen as the Node it is.
    pub fn asNode(self: Other) Node {
        return self.node;
    }
};
